agricultural_employer_threshold.binding_program:
def case_witnesses(public):
    result = []
    facts = public.get('facts')
    question = public.get('question')
    if type(facts) is str and facts:
        result.append({'field': 'facts', 'quote': facts})
    if type(question) is str and question:
        result.append({'field': 'question', 'quote': question})
    return result


def supported(record, public):
    if type(record) is not dict:
        return False
    field = record.get('source_field')
    quote = record.get('quote')
    text = public.get(field)
    return field in ('facts', 'question') and type(quote) is str and bool(quote) and type(text) is str and quote in text


def payment_event(record):
    result = {}
    for key in ('payer', 'payee', 'stated_labor', 'amount', 'period_start', 'period_end', 'wages_given'):
        if key in record:
            result[key] = record.get(key)
    return result


def apply(inputs, premises):
    public = inputs.get('public_case', {})
    literal = inputs.get('literal_context', {})
    values = literal.get('values', {}) if type(literal) is dict else {}
    observation = inputs.get('observation')
    witnesses = case_witnesses(public)
    if type(observation) is not dict or type(observation.get('views')) is not list:
        return {'bindings': [], 'unresolved': ['A source-backed payment-event observation is required.']}
    bindings = []
    unresolved = set()
    literal_claimant = values.get('claimant')
    literal_year = values.get('query_year')
    if type(literal_year) is not int:
        literal_year = values.get('year')
    for view in observation.get('views'):
        if type(view) is not dict:
            unresolved.add('A payment view was not a declared record.')
            continue
        claimant = literal_claimant if type(literal_claimant) is str else None
        query_year = literal_year if type(literal_year) is int else None
        claimant_record = view.get('claimant')
        year_record = view.get('query_year')
        if claimant is None and supported(claimant_record, public) and claimant_record.get('source_field') == 'question':
            if type(claimant_record.get('value')) is str:
                claimant = claimant_record.get('value')
        if query_year is None and supported(year_record, public) and year_record.get('source_field') == 'question':
            if type(year_record.get('value')) is int:
                query_year = year_record.get('value')
        if claimant is None:
            unresolved.add('The claimant is not grounded in the current question.')
        if query_year is None:
            unresolved.add('The query year is not grounded in the current question.')
        raw_events = view.get('payment_events')
        events = []
        status = view.get('payment_events_extraction_status')
        if status not in ('resolved', 'unknown', 'failed'):
            status = 'failed'
        if type(raw_events) is list:
            for record in raw_events:
                if not supported(record, public):
                    status = 'failed'
                    continue
                event = payment_event(record)
                for key in ('payer', 'payee', 'stated_labor', 'amount', 'period_start', 'period_end', 'wages_given'):
                    if key not in event:
                        status = 'unknown'
                events.append(event)
        else:
            status = 'failed'
        grounded = {'payment_events': events, 'payment_events_extraction_status': status}
        if claimant is not None:
            grounded['claimant'] = claimant
        if query_year is not None:
            grounded['query_year'] = query_year
        if witnesses:
            bindings.append({'inputs': grounded, 'witnesses': witnesses})
        else:
            unresolved.add('The current case supplies no nonempty factual or question witness.')
    if not bindings:
        unresolved.add('No coherent payment-event binding was constructed.')
    return {'bindings': bindings, 'unresolved': sorted(unresolved)}

